import java.lang.annotation.*;import java.lang.reflect.*;import java.util.*;
public class MiniBank {
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD) @interface Id {}
    static class Account {@Id private final String accountNumber;private final String owner;private final long balance;Account(String n,String o,long b){accountNumber=n;owner=o;balance=b;}public String toString(){return accountNumber+" "+owner+" balance="+balance;}}
    static class Customer {@Id private final String customerId;private final String name;Customer(String i,String n){customerId=i;name=n;}public String toString(){return customerId+" "+name;}}
    static class Repository<T>{private final HashMap<String,T> values=new HashMap<>();T save(T entity){try{for(Class<?> c=entity.getClass();c!=null;c=c.getSuperclass())for(Field f:c.getDeclaredFields())if(f.isAnnotationPresent(Id.class)){f.setAccessible(true);String id=String.valueOf(f.get(entity));values.put(id,entity);return entity;}throw new IllegalArgumentException("No @Id field found");}catch(IllegalAccessException e){throw new IllegalStateException(e);}}T findById(String id){return values.get(id);}ArrayList<T> findAll(){return new ArrayList<>(values.values());}boolean delete(String id){return values.remove(id)!=null;}@SafeVarargs final void saveAll(T... items){for(T t:items)save(t);}static <N extends Number> double average(N[] a){if(a.length==0)return 0;double s=0;for(N n:a)s+=n.doubleValue();return s/a.length;}}
    public static void main(String[] args){Repository<Account> r=new Repository<>();r.saveAll(new Account("AC0001","Aarav",5000),new Account("AC0002","Diya",2000),new Account("AC0003","Kabir",9000));System.out.println("Found: "+r.findById("AC0002"));for(Account a:r.findAll())System.out.println(a);Repository<Customer> c=new Repository<>();c.save(new Customer("CUST101","Diya"));System.out.println("Customer: "+c.findById("CUST101"));System.out.println("Average: "+Repository.average(new Integer[]{2,4,6}));}
}
